data.default.conf:
map $http_upgrade $connection_upgrade {
  default upgrade;
  '' close;
}
server {
  listen 8080 ssl;
  ssl_certificate /certs/edge.pem;
  ssl_certificate_key /certs/edge-key.pem;

  server_name localhost;
  client_max_body_size 100m;
  proxy_http_version 1.1;
  proxy_set_header Host localhost:8443;
  proxy_set_header X-Forwarded-Proto https;
  # Keep every header at server level: nginx drops all inherited proxy_set_header
  # directives in a location that declares any of its own.
  proxy_set_header Upgrade $http_upgrade;
  proxy_set_header Connection $connection_upgrade;
  proxy_read_timeout 3600s;
  proxy_send_timeout 3600s;
  proxy_buffering off;
  proxy_ssl_verify on;
  proxy_ssl_trusted_certificate /ca/rootCA.pem;
  proxy_ssl_server_name on;
  location ~ ^/(?:api(?:/|$)|openapi\.json$|api-docs(?:/|$)|health$|ready$|about$) {
    proxy_pass http://api:80;
  }
  location ~ ^/(?:11111111-1111-1111-1111-111111111111|common|organizations|consumers)/(?:v2\.0/\.well-known/openid-configuration$|discovery/v2\.0/keys$|oauth2/v2\.0(?:/|$)) {
    proxy_pass https://entra-local:8443;
  }
  location = /graph/oidc/userinfo {
    proxy_pass https://entra-local:8443;
  }
  location ~ ^/(?:admin(?:/|$)|graph(?:/|$)|(?:11111111-1111-1111-1111-111111111111|common|organizations|consumers)(?:/|$)|[^/]+/(?:v2\.0|discovery|oauth2|openid)(?:/|$)) {
    return 404;
  }
  location / {
    proxy_pass http://portal:5100;
  }
}

